-- 栈基础：单链表表头上的常数时间栈操作。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '链栈','链栈以单链表表头为栈顶，push 与 pop 都只改接表头指针。',course.id,parent.id,'cs408-linked-stack','AISTU',1,'REVIEWED',3,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-linked-stack' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-linked-stack',1,'REVIEWED','链栈',JSON_OBJECT('summary','链栈让 top 指向单链表表头。push 创建新结点，让其 next 指向旧 top 后更新 top；pop 保存 top 数据并让 top 指向后继。只要分配成功就不受固定容量限制，但每个结点有指针开销。','steps',JSON_ARRAY('top 指向栈顶，也就是链表表头','push 先令新结点 next 指向旧 top','再更新 top 到新结点','pop 保存表头数据并把 top 指向后继','表头插删均为 O(1)，但结点有指针开销'),'prerequisite',JSON_OBJECT('contentKey','cs408-stack-lifo','title','栈的 LIFO 语义与基本操作','description','先确认栈顶是唯一更新端。'),'nextStep',JSON_OBJECT('contentKey','cs408-stack-pop-sequences','title','合法出栈序列','description','继续通过辅助栈模拟固定入栈顺序。')),JSON_OBJECT('id','linked-stack-v1','prompt','链栈为何通常把单链表的哪一端作为栈顶？','options',JSON_ARRAY(JSON_OBJECT('id','HEAD_PUSH','text','表头，因为插入和删除都无需遍历'),JSON_OBJECT('id','TAIL_PUSH','text','表尾，因为链表只能从尾部读取')),'correctOptionId','HEAD_PUSH','correctExplanation','正确：已知表头时在表头插删都是 O(1)，正好满足栈顶操作。','incorrectExplanation','不正确：单链表若没有尾前驱，在表尾删除通常需要遍历。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-linked-stack' AND existing.content_version=1 WHERE point.content_key='cs408-linked-stack' AND existing.id IS NULL;
